mapper.select:
SELECT CASE WHEN EXISTS(
    SELECT 1 FROM chat_turn turn JOIN chat_session session ON session.id=turn.session_id
    WHERE turn.id=#{requestId,typeHandler=com.febridge.persistence.UuidTypeHandler}
        AND session.agent_id=#{agentId,typeHandler=com.febridge.persistence.UuidTypeHandler}
        AND session.owner_user_id=#{ownerId,typeHandler=com.febridge.persistence.UuidTypeHandler}
) OR EXISTS(
    SELECT 1 FROM agent_run_event WHERE
        request_id=#{requestId,typeHandler=com.febridge.persistence.UuidTypeHandler}
        AND agent_id=#{agentId,typeHandler=com.febridge.persistence.UuidTypeHandler}
        AND owner_user_id=#{ownerId,typeHandler=com.febridge.persistence.UuidTypeHandler}
) THEN 1 ELSE 0 END

SELECT * FROM agent_run_event WHERE agent_id=#{agentId,typeHandler=com.febridge.persistence.UuidTypeHandler}
AND request_id=#{requestId,typeHandler=com.febridge.persistence.UuidTypeHandler}
ORDER BY id LIMIT 100
